'use strict';
function reviewPolicyHTML() {
  const p = ReviewPolicy.data,
    escape = (s) =>
      String(s ?? '').replace(
        /[&<>"']/g,
        (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c],
      );
  const link = (url, label) =>
    `<a href="${escape(url)}" target="_blank" rel="noopener">${escape(label)} ↗</a>`;
  return `<section class="panel panel-pad policy-intro"><div class="eyebrow">REVIEW RUBRIC V3 · SELECTED TEXT POLICIES</div><h2>Context first. A specific rule next.</h2><p class="body-copy">${escape(p.scope)}</p><div class="policy-dates"><span>Guidelines effective <strong>24 September 2026</strong></span><span>Sources checked <strong>6 November 2026</strong></span></div><p class="help-text">English (US) source pages, released 25 August 2026. This is our operational interpretation of selected TikTok rules, not TikTok’s own enforcement tool. Examples below are written for this prototype.</p><div class="resource-links">${p.sources.map((s) => link(s.url, s.title)).join('')}</div></section>
  <div class="policy-actions">${p.decisions.map((d) => `<section class="panel panel-pad"><span class="eyebrow">${escape(d.id === 'Escalate' ? 'CONTEXT' : d.id.toUpperCase())}</span><h3>${escape(d.title)}</h3><p>${escape(d.detail)}</p></section>`).join('')}</div>
  <section class="panel panel-pad policy-intro"><h2>A repeatable review</h2><ol class="policy-steps"><li><strong>Read the target and context.</strong> Use available caption, thread and media evidence. Record what you have not reviewed.</li><li><strong>Identify the act and stance.</strong> Find a mapped prohibition. Distinguish endorsement from quotation, reporting, counterspeech and sarcasm.</li><li><strong>Check exceptions and missing evidence.</strong> A plausible concern with unclear intent needs context. Unclear grammar alone does not.</li><li><strong>Record action, reason and priority.</strong> Cite evidence for a flag or escalation. Urgent means a priority marker only; this prototype does not contact a safety team or emergency service.</li></ol></section>
  <div class="section-grid policy-categories">${p.categories.map((c) => `<article class="panel panel-pad policy-category" id="policy-${c.id}"><div class="eyebrow">${escape(c.section)}</div><h2>${escape(c.title)}</h2><p class="body-copy"><strong>What qualifies:</strong> ${escape(c.rule)}</p><p class="body-copy"><strong>Boundary:</strong> ${escape(c.exception)}</p><div class="policy-examples">${c.examples.map((e) => `<div class="policy-example"><span class="policy-label ${e.decision === 'Violation' ? 'violation' : e.decision === 'No violation' ? 'allowed' : 'context'}">${escape(e.decision)}</span><blockquote>${escape(e.text)}</blockquote><p>${escape(e.why)}</p></div>`).join('')}</div><div class="resource-links">${link(c.url, 'Read the TikTok rule')}${c.secondary_url ? link(c.secondary_url, 'Doxing and harassment') : ''}</div></article>`).join('')}</div>
  <section class="panel panel-pad policy-intro"><h2>Where judgment matters</h2><ul class="policy-steps">${p.boundaries.map((t) => `<li>${escape(t)}</li>`).join('')}</ul><p class="body-copy"><strong>Protected attributes in the source:</strong> ${p.protected_attributes.map(escape).join(', ')}. Age and regional rules can add protections; consult the linked source for the specific case.</p></section>
  <section class="panel panel-pad policy-intro"><div class="eyebrow">CALIBRATION NOTES</div><h2>Our first two human decisions</h2>${p.calibration.map((c) => `<p class="body-copy"><strong>${escape(c.id)} · ${escape(c.decision)}:</strong> ${escape(c.summary)} <span class="label-subtle">${escape(c.uncertainty)}</span></p>`).join('')}<p class="help-text">${escape(p.calibration_note)}</p></section>
  <section class="panel panel-pad policy-intro"><h2>What changed from v2?</h2><p class="body-copy">${escape(p.migration_note)}</p><p class="body-copy">Previous annotations and the six-case error audit remain historical. Re-review them explicitly under v3 before using them as policy evaluation labels. The Civil Comments model, reference labels and benchmark results remain frozen.</p><div class="actions-row no-print"><a class="button" href="rubric.html" target="_blank" rel="noopener">Open printable guide ↗</a></div><p class="help-text">Policy version: ${escape(p.version)}</p></section>`;
}
